<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { ArrowDownLeft, ArrowUpRight, CreditCard, FileDown, LoaderCircle, Pause, Play, Plus, ReceiptText, RotateCcw, X } from "lucide-vue-next";
import { useRoute } from "vue-router";
import DataPanel from "@/components/operations/DataPanel.vue";
import OpsModal from "@/components/operations/OpsModal.vue";
import StatusBadge from "@/components/operations/StatusBadge.vue";
import { platformRepository } from "@/data/repositories/platformRepository";
import { operationsRepository } from "@/data/repositories/operationsRepository";
import type { UiPlan } from "@/data/models/platform";
import type { UiCommissionRecord, UiInvoiceRecord, UiPaymentRecord, UiStudentRecord, UiSubscriptionRecord } from "@/data/models/operations";

const route = useRoute();
const loading = ref(true); const saving = ref(false); const actionId = ref<number | null>(null); const error = ref("");
const students = ref<UiStudentRecord[]>([]); const subscriptions = ref<UiSubscriptionRecord[]>([]); const plans = ref<UiPlan[]>([]); const platformFees = ref<UiCommissionRecord[]>([]); const earnings = ref<UiCommissionRecord[]>([]); const invoices = ref<UiInvoiceRecord[]>([]); const payments = ref<UiPaymentRecord[]>([]);
const selectedStudent = ref(0); const selectedPlan = ref(0); const showCreate = ref(false);
type PromoRow = { id:number; name:string; code:string; discount_type:string; amount_minor?:number|null; percentage?:number|null; max_redemptions?:number|null; per_user_limit:number; redemptions_count:number; starts_at?:string|null; ends_at?:string|null; is_active:boolean; plans?:Array<{id:number;name:string}> };
const promoCodes = ref<PromoRow[]>([]); const showPromoCreate = ref(false); const promoReport = ref<Record<string, any> | null>(null);
const promoForm = ref({ name:"", code:"", discount_type:"percentage", percentage:10, amount_minor:0, max_redemptions:100, per_user_limit:1, starts_at:"", ends_at:"", plan_ids:[] as number[], is_active:true });
const instituteId = () => Number(route.params.instituteId);
const money = (minor: number, currency: string) => new Intl.NumberFormat(undefined, { style: "currency", currency }).format(minor / 100);
const payable = computed(() => earnings.value.filter((item) => !["paid", "reversed"].includes(item.status)).reduce((sum, item) => sum + item.netAmountMinor, 0));
const retained = computed(() => platformFees.value.reduce((sum, item) => sum + item.netAmountMinor, 0));
const settlementCurrency = computed(() => platformFees.value[0]?.currency || earnings.value[0]?.currency || "PKR");

async function load() {
  loading.value = true; error.value = "";
  try {
    const [studentPage, subscriptionPage, catalog, feePage, earningPage, invoicePage, paymentPage, promoPage] = await Promise.all([
      operationsRepository.students({ institute_id: instituteId(), per_page: 100 }),
      operationsRepository.subscriptions({ per_page: 100 }), platformRepository.catalog(),
      operationsRepository.institutePlatformFees(instituteId(), { per_page: 100 }), operationsRepository.instituteEarnings(instituteId(), { per_page: 100 }),
      operationsRepository.invoices({ per_page: 100 }), operationsRepository.payments({ per_page: 100 }),
      operationsRepository.institutePromoCodes(instituteId()),
    ]);
    students.value = studentPage.items;
    const userIds = new Set(students.value.map((item) => item.userId));
    subscriptions.value = subscriptionPage.items.filter((item) => userIds.has(item.subscriberId));
    plans.value = catalog.plans; platformFees.value = feePage.items; earnings.value = earningPage.items; invoices.value = invoicePage.items; payments.value = paymentPage.items; promoCodes.value = promoPage.data;
  } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to load billing."; }
  finally { loading.value = false; }
}
async function subscribe() {
  if (!selectedStudent.value || !selectedPlan.value) return; saving.value = true;
  try { await operationsRepository.createSubscription(selectedStudent.value, selectedPlan.value); showCreate.value = false; selectedStudent.value = 0; selectedPlan.value = 0; await load(); }
  catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to create subscription."; }
  finally { saving.value = false; }
}
async function state(item: UiSubscriptionRecord, action: "cancel" | "resume" | "pause" | "activate") {
  actionId.value = item.id;
  try { await operationsRepository.changeSubscription(item.id, action); await load(); }
  catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to change subscription."; }
  finally { actionId.value = null; }
}
async function createPromo() {
  saving.value = true; error.value = "";
  try { const f = promoForm.value; await operationsRepository.createInstitutePromoCode(instituteId(), { ...f, code:f.code.toUpperCase(), amount_minor: f.discount_type === "fixed" ? Math.round(Number(f.amount_minor)) : null, percentage: f.discount_type === "percentage" ? Number(f.percentage) : null, starts_at:f.starts_at || null, ends_at:f.ends_at || null, max_redemptions:f.max_redemptions || null }); showPromoCreate.value=false; promoForm.value={ name:"", code:"", discount_type:"percentage", percentage:10, amount_minor:0, max_redemptions:100, per_user_limit:1, starts_at:"", ends_at:"", plan_ids:[], is_active:true }; await load(); }
  catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to create promo code."; } finally { saving.value=false; }
}
async function viewPromoReport(id:number) { try { promoReport.value = (await operationsRepository.institutePromoReport(instituteId(), id)).data; } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to load promo report."; } }

onMounted(load);
</script>

<template>
  <div class="space-y-5">
    <div class="flex flex-wrap items-end justify-between gap-3"><div><p class="text-[12px] font-semibold uppercase tracking-[0.12em] text-gold">Platform-collected billing</p><h2 class="mt-1 text-[26px] font-bold tracking-[-0.035em]">Billing</h2><p class="mt-1 text-[13px] text-ink3">Student payments are collected by the platform. Institute credits and retained platform charges are shown below.</p></div><button class="ops-button-primary flex items-center gap-2" @click="showCreate = true"><Plus :size="15" /> New subscription</button></div>
    <p v-if="error" class="rounded-xl bg-pink-light px-4 py-3 text-[13px] text-pink">{{ error }}</p>
    <div class="grid gap-3 sm:grid-cols-2"><article class="rounded-2xl border border-border bg-bg-card p-4"><ArrowDownLeft :size="18" class="text-mint" /><p class="mt-3 text-[11px] text-ink3">Institute earnings payable by platform</p><strong class="text-[23px]">{{ money(payable, settlementCurrency) }}</strong><p class="mt-1 text-[10px] text-ink4">Separate from platform service fees</p></article><article class="rounded-2xl border border-border bg-bg-card p-4"><ArrowUpRight :size="18" class="text-pink" /><p class="mt-3 text-[11px] text-ink3">Net platform service fees</p><strong class="text-[23px]">{{ money(retained, settlementCurrency) }}</strong><p class="mt-1 text-[10px] text-ink4">After refund reversals</p></article></div>
    <DataPanel title="Institute promo codes" :description="`${promoCodes.length} codes · successful usage is counted only after successful payment`" :loading="loading" :empty="!promoCodes.length"><template #actions><button class="ops-button-primary inline-flex items-center gap-1.5" @click="showPromoCreate = true"><Plus :size="13" /> New promo code</button></template><div class="overflow-x-auto"><table class="w-full min-w-[760px] text-left text-[12px]"><thead class="bg-bg-soft text-ink3"><tr><th class="px-5 py-3">Code</th><th class="px-4 py-3">Discount</th><th class="px-4 py-3">Eligible plans</th><th class="px-4 py-3">Usage</th><th class="px-4 py-3">Validity</th><th class="px-5 py-3 text-right">Reporting</th></tr></thead><tbody class="divide-y divide-border"><tr v-for="promo in promoCodes" :key="promo.id"><td class="px-5 py-3.5"><p class="font-mono font-semibold">{{ promo.code }}</p><p class="text-[10px] text-ink3">{{ promo.name }}</p></td><td class="px-4 py-3.5">{{ promo.discount_type === 'percentage' ? `${promo.percentage}%` : money(promo.amount_minor || 0, settlementCurrency) }}</td><td class="px-4 py-3.5">{{ promo.plans?.length ? promo.plans.map(p => p.name).join(', ') : 'All eligible plans' }}</td><td class="px-4 py-3.5">{{ promo.redemptions_count }} / {{ promo.max_redemptions ?? '∞' }}<p class="text-[10px] text-ink3">{{ promo.per_user_limit }} per student</p></td><td class="px-4 py-3.5">{{ promo.starts_at ? new Date(promo.starts_at).toLocaleDateString() : 'Now' }} – {{ promo.ends_at ? new Date(promo.ends_at).toLocaleDateString() : 'No expiry' }}</td><td class="px-5 py-3.5 text-right"><button class="ops-button-secondary" @click="viewPromoReport(promo.id)">View report</button></td></tr></tbody></table></div></DataPanel>
    <DataPanel title="Student subscriptions" :description="`${subscriptions.length} records`" :loading="loading" :empty="!subscriptions.length"><div class="grid gap-4 p-5 md:grid-cols-2 xl:grid-cols-3"><article v-for="item in subscriptions" :key="item.id" class="rounded-2xl border border-border p-4"><div class="flex items-start justify-between"><div class="grid h-9 w-9 place-items-center rounded-xl bg-gold-light text-gold"><CreditCard :size="17" /></div><StatusBadge :value="item.status" /></div><h3 class="mt-4 text-[14px] font-bold">{{ item.planName }}</h3><p class="mt-1 text-[11px] text-ink3">Student user #{{ item.subscriberId }}</p><p class="mt-3 text-[11px] text-ink2">Period ends {{ item.periodEnd ? new Date(item.periodEnd).toLocaleDateString() : '—' }}</p><div class="mt-4 flex gap-2 border-t border-border pt-3"><button v-if="item.status === 'active'" :disabled="actionId === item.id" class="ops-button-secondary flex items-center gap-1.5" @click="state(item, 'pause')"><LoaderCircle v-if="actionId === item.id" :size="13" class="animate-spin" /><Pause v-else :size="13" /> Pause</button><button v-if="item.status === 'paused'" :disabled="actionId === item.id" class="ops-button-secondary flex items-center gap-1.5" @click="state(item, 'activate')"><Play :size="13" /> Activate</button><button v-if="item.cancelAtPeriodEnd" class="ops-button-secondary flex items-center gap-1.5" @click="state(item, 'resume')"><RotateCcw :size="13" /> Resume</button></div></article></div></DataPanel>
    <div class="grid gap-5 xl:grid-cols-2">
      <DataPanel title="Platform fee statement" :description="`${platformFees.length} fee entries`" :loading="loading" :empty="!platformFees.length"><div class="overflow-x-auto"><table class="w-full min-w-[620px] text-left text-[12px]"><thead class="bg-bg-soft text-ink3"><tr><th class="px-5 py-3">Student</th><th class="px-4 py-3">Gross</th><th class="px-4 py-3">Reversed</th><th class="px-4 py-3">Net fee</th><th class="px-4 py-3">Status</th></tr></thead><tbody class="divide-y divide-border"><tr v-for="item in platformFees" :key="item.id"><td class="px-5 py-3.5">User #{{ item.studentUserId }}</td><td class="px-4 py-3.5">{{ money(item.amountMinor, item.currency) }}</td><td class="px-4 py-3.5 text-pink">{{ money(item.reversedAmountMinor, item.currency) }}</td><td class="px-4 py-3.5 font-semibold">{{ money(item.netAmountMinor, item.currency) }}</td><td class="px-4 py-3.5"><StatusBadge :value="item.status" /></td></tr></tbody></table></div></DataPanel>
      <DataPanel title="Institute earnings statement" :description="`${earnings.length} earning entries`" :loading="loading" :empty="!earnings.length"><div class="overflow-x-auto"><table class="w-full min-w-[620px] text-left text-[12px]"><thead class="bg-bg-soft text-ink3"><tr><th class="px-5 py-3">Student</th><th class="px-4 py-3">Gross</th><th class="px-4 py-3">Reversed</th><th class="px-4 py-3">Net earning</th><th class="px-4 py-3">Status</th></tr></thead><tbody class="divide-y divide-border"><tr v-for="item in earnings" :key="item.id"><td class="px-5 py-3.5">User #{{ item.studentUserId }}</td><td class="px-4 py-3.5">{{ money(item.amountMinor, item.currency) }}</td><td class="px-4 py-3.5 text-pink">{{ money(item.reversedAmountMinor, item.currency) }}</td><td class="px-4 py-3.5 font-semibold">{{ money(item.netAmountMinor, item.currency) }}</td><td class="px-4 py-3.5"><StatusBadge :value="item.status" /></td></tr></tbody></table></div></DataPanel>
    </div>
    <DataPanel title="Invoice and payment statement" :description="`${invoices.length} invoices · ${payments.length} payment attempts`" :loading="loading" :empty="!invoices.length"><div class="overflow-x-auto"><table class="w-full min-w-[820px] text-left text-[12px]"><thead class="bg-bg-soft text-ink3"><tr><th class="px-5 py-3">Invoice</th><th class="px-4 py-3">Total</th><th class="px-4 py-3">Gross paid</th><th class="px-4 py-3">Refunded</th><th class="px-4 py-3">Net paid</th><th class="px-4 py-3">Status</th><th class="px-5 py-3 text-right">Documents</th></tr></thead><tbody class="divide-y divide-border"><tr v-for="item in invoices" :key="item.id"><td class="px-5 py-3.5 font-mono">{{ item.number }}</td><td class="px-4 py-3.5 font-semibold">{{ money(item.totalMinor, item.currency) }}</td><td class="px-4 py-3.5">{{ money(item.paidMinor, item.currency) }}</td><td class="px-4 py-3.5">{{ money(item.refundedMinor, item.currency) }}</td><td class="px-4 py-3.5 font-semibold">{{ money(Math.max(0, item.paidMinor - item.refundedMinor), item.currency) }}</td><td class="px-4 py-3.5"><StatusBadge :value="item.status" /></td><td class="px-5 py-3.5"><div class="flex justify-end gap-1"><button class="ops-icon-button" title="Download invoice" @click="operationsRepository.downloadInvoice(item.id, item.number)"><FileDown :size="14" /></button><button v-for="payment in payments.filter((payment) => payment.invoiceId === item.id && payment.receiptNumber)" :key="payment.id" class="ops-icon-button" title="Download receipt" @click="operationsRepository.downloadReceipt(payment.id, payment.receiptNumber)"><ReceiptText :size="14" /></button></div></td></tr></tbody></table></div></DataPanel>
    <OpsModal :open="showPromoCreate" max-width="max-w-2xl" :close-on-backdrop="!saving" @close="showPromoCreate = false"><form class="rounded-2xl border border-border bg-bg-card p-5 shadow-2xl" @submit.prevent="createPromo"><div class="mb-5 flex justify-between"><div><h3 class="text-[17px] font-bold">New institute promo code</h3><p class="mt-1 text-[12px] text-ink3">Owned by this institute and usable only by its students.</p></div><button type="button" @click="showPromoCreate=false"><X :size="18" /></button></div><div class="grid gap-3 md:grid-cols-2"><label class="text-[11px] font-semibold">Name<input v-model="promoForm.name" required class="ops-input" /></label><label class="text-[11px] font-semibold">Code<input v-model="promoForm.code" required maxlength="80" class="ops-input uppercase" placeholder="SCHOOL20" /></label><label class="text-[11px] font-semibold">Discount type<select v-model="promoForm.discount_type" class="ops-input"><option value="percentage">Percentage</option><option value="fixed">Fixed amount (minor units)</option></select></label><label v-if="promoForm.discount_type === 'percentage'" class="text-[11px] font-semibold">Percentage<input v-model.number="promoForm.percentage" type="number" min="0.01" max="100" step="0.01" class="ops-input" /></label><label v-else class="text-[11px] font-semibold">Fixed amount (minor units)<input v-model.number="promoForm.amount_minor" type="number" min="1" class="ops-input" /></label><label class="text-[11px] font-semibold">Total usage limit<input v-model.number="promoForm.max_redemptions" type="number" min="1" class="ops-input" /></label><label class="text-[11px] font-semibold">Per-student limit<input v-model.number="promoForm.per_user_limit" type="number" min="1" class="ops-input" /></label><label class="text-[11px] font-semibold">Starts<input v-model="promoForm.starts_at" type="datetime-local" class="ops-input" /></label><label class="text-[11px] font-semibold">Ends<input v-model="promoForm.ends_at" type="datetime-local" class="ops-input" /></label><label class="md:col-span-2 text-[11px] font-semibold">Eligible plans<select v-model="promoForm.plan_ids" multiple class="ops-input min-h-28"><option v-for="plan in plans" :key="plan.id" :value="plan.id">{{ plan.name }}</option></select><span class="mt-1 block font-normal text-ink4">Leave empty for all plans available to institute students.</span></label></div><div class="mt-5 flex justify-end gap-2"><button type="button" class="ops-button-secondary" @click="showPromoCreate=false">Cancel</button><button :disabled="saving" class="ops-button-primary">{{ saving ? 'Saving…' : 'Create promo code' }}</button></div></form></OpsModal>
    <OpsModal :open="Boolean(promoReport)" max-width="max-w-xl" @close="promoReport = null"><div class="rounded-2xl border border-border bg-bg-card p-5 shadow-2xl"><div class="flex justify-between"><div><h3 class="text-[17px] font-bold">Promo code report</h3><p class="mt-1 font-mono text-[12px] text-ink3">{{ promoReport?.promo?.code }}</p></div><button @click="promoReport=null"><X :size="18" /></button></div><div class="mt-5 grid grid-cols-2 gap-3"><div class="rounded-xl bg-bg-soft p-3"><p class="text-[10px] text-ink3">Successful uses</p><strong>{{ promoReport?.summary?.successful_redemptions || 0 }}</strong></div><div class="rounded-xl bg-bg-soft p-3"><p class="text-[10px] text-ink3">Pending payments</p><strong>{{ promoReport?.summary?.pending_redemptions || 0 }}</strong></div><div class="rounded-xl bg-bg-soft p-3"><p class="text-[10px] text-ink3">Unique students</p><strong>{{ promoReport?.summary?.unique_users || 0 }}</strong></div><div class="rounded-xl bg-bg-soft p-3"><p class="text-[10px] text-ink3">Discount given</p><strong>{{ money(promoReport?.summary?.total_discount_minor || 0, settlementCurrency) }}</strong></div></div></div></OpsModal>
    <OpsModal :open="showCreate" max-width="max-w-lg" :close-on-backdrop="!saving" @close="showCreate = false"><form class="rounded-2xl border border-border bg-bg-card p-5 shadow-2xl" @submit.prevent="subscribe"><div class="mb-5 flex items-start justify-between"><div><h3 class="text-[17px] font-bold">New subscription</h3><p class="mt-1 text-[12px] text-ink3">Creates the subscription and invoice. The platform checkout collects payment from the student.</p></div><button type="button" :disabled="saving" @click="showCreate = false"><X :size="18" /></button></div><div class="space-y-3"><label class="text-[11px] font-semibold">Student<select v-model.number="selectedStudent" required class="ops-input"><option :value="0">Select student</option><option v-for="student in students" :key="student.id" :value="student.id">{{ student.name }}</option></select></label><label class="text-[11px] font-semibold">Plan<select v-model.number="selectedPlan" required class="ops-input"><option :value="0">Select plan</option><option v-for="plan in plans" :key="plan.id" :value="plan.id">{{ plan.name }} — {{ money(plan.priceMinor, plan.currency) }}</option></select></label></div><div class="mt-5 flex justify-end gap-2"><button type="button" class="ops-button-secondary" @click="showCreate = false">Cancel</button><button :disabled="saving" class="ops-button-primary inline-flex min-w-28 items-center justify-center gap-2"><LoaderCircle v-if="saving" :size="14" class="animate-spin" />{{ saving ? 'Creating…' : 'Create invoice' }}</button></div></form></OpsModal>
  </div>
</template>
